import assert from 'node:assert/strict';
import { createProgressFeed } from './src/progress-source.js';
import { watchTransferProgress } from './src/progress.js';
import { collectProgressTelemetry } from './src/telemetry.js';

const shown = [];
const recorded = [];
const initial = createProgressFeed({ initialPacket: { id: 'initial' } });
const stopInitial = watchTransferProgress(initial, frame => shown.push(frame.id), frame => recorded.push(frame.id));
initial.emit({ id: 'later' });
assert.deepEqual(recorded, ['initial', 'later']);
assert.deepEqual(shown, ['initial', 'later']);
stopInitial();

const pending = new Map();
const ordered = createProgressFeed({ decode(packet) { return new Promise(resolve => pending.set(packet.id, resolve)); } });
const display = [];
const history = [];
const stopOrdered = watchTransferProgress(ordered, frame => display.push(frame.id), frame => history.push(frame.id));
ordered.emit({ id: 'older' });
ordered.emit({ id: 'newer' });
pending.get('newer')({ id: 'newer' });
pending.get('older')({ id: 'older' });
await Promise.resolve();
assert.deepEqual(history, ['newer', 'older']);
assert.deepEqual(display, ['newer']);
stopOrdered();

const telemetry = [];
const diagnostic = createProgressFeed({ initialPacket: 'cached' });
const stopTelemetry = collectProgressTelemetry(diagnostic, frame => telemetry.push(frame));
diagnostic.emit('live');
assert.deepEqual(telemetry, ['live']);
stopTelemetry();
console.log('progress behavior checks passed');
EOF

