const records = [], queued = [], progress = [], shown = [], transports = [], cancelled = [];
const feed = createProgressFeed({ initialPacket: { loaded: 1 } });
const workspace = createTransferWorkspace({
  transport: event => transports.push(event),
  onCancel: event => cancelled.push(event.attemptId),
  record: entry => records.push(entry),
  showQueued: entry => queued.push(entry),
  recordProgress: entry => progress.push(entry),
  showProgress: entry => shown.push(entry),
});
const file = { id: 'one', progressFeed: feed };
const first = workspace.select(file);
assert.equal(first.attemptId, 1);
assert.deepEqual(records, [{ fileId: 'one', attemptId: 1, visitId: 1, kind: 'select' }]);
assert.equal(queued.length, 1);
assert.equal(transports.length, 1);
assert.deepEqual(progress.map(x => x.frame.loaded), [1]);
assert.deepEqual(shown.map(x => x.frame.loaded), [1]);
